pous.declaration:
FUNCTION_BLOCK ConstPressure
VAR_INPUT
    pressure : REAL;
    setpoint : REAL;
    deadband : REAL;
END_VAR
VAR_OUTPUT
    pump1Run : BOOL;
    pump2Run : BOOL;
    pump3Run : BOOL;
END_VAR
VAR
    n : INT := 0;
    delayTon : TON;
END_VAR

pous.implementation:
IF pressure < setpoint - deadband AND n < 3 THEN
    n := n + 1;
ELSIF pressure > setpoint + deadband AND n > 0 THEN
    n := n - 1;
END_IF
pump1Run := (n >= 1);
pump2Run := (n >= 2);
pump3Run := (n >= 3);
